"""Create report and board deck from reproducible metrics."""
from pathlib import Path
import json
from docx import Document
from docx.shared import Inches,Pt
from reportlab.lib import colors
from reportlab.lib.pagesizes import letter,landscape
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak
from pptx import Presentation
from pptx.util import Inches as PI,Pt as PP
from pptx.dml.color import RGBColor
R=Path(__file__).resolve().parents[1]; O=R/'deliverables'; M=json.load(open(O/'metrics.json'))
N={'DEU':'Germany','FRA':'France','NLD':'Netherlands','POL':'Poland','CZE':'Czechia','ESP':'Spain'}
def eur(n):return f'€{n:,.0f}'
countries=M['countries']; totals={k:sum(x[k] for x in countries) for k in ['shipped_orders','shipped_units','gross_sales_eur','refunds_eur','net_sales_eur','net_cogs_eur','fulfillment_eur','contribution_eur']}
margin=totals['contribution_eur']/totals['net_sales_eur']; alts=M['alternatives']; best,second=alts[:2]; rec=M['recommendation']; names=' + '.join(N[c] for c in rec['countries']); bestnames=' + '.join(best['countries']); secondnames=' + '.join(second['countries']); q=M['quality']['reconciliation']
ctx=M['market_context']; popdelta={c:100*(next(x['population'] for x in ctx if x['country']==c and x['year']==2024)/next(x['population'] for x in ctx if x['country']==c and x['year']==2022)-1) for c in N}; gdps={c:next(x['gdp_per_capita_usd'] for x in ctx if x['country']==c and x['year']==2024) for c in N}; gdphi=max(gdps,key=gdps.get); gdplo=min(gdps,key=gdps.get)

# Full-length executive report in DOCX.
d=Document(); sec=d.sections[0]; sec.top_margin=Inches(.65);sec.bottom_margin=Inches(.65);sec.left_margin=Inches(.7);sec.right_margin=Inches(.7)
d.styles['Normal'].font.name='Aptos';d.styles['Normal'].font.size=Pt(9)
d.add_heading('European service-hub expansion',0);d.add_paragraph('Meridian Parts | Board decision paper | 27 September 2026',style='Subtitle')
d.add_heading('Recommendation: advance a gated investment case',1)
d.add_paragraph(f"Advance {names} as the leading case, with {eur(rec['capex_eur'])} capex and {rec['fte']} FTE. It ranks first among feasible portfolios on base annual incremental contribution ({eur(best['base_annual_incremental_eur'])}) and remains positive in policy low volume ({eur(best['low_annual_incremental_eur'])}) and joint return/FX stress ({eur(best['stress_annual_incremental_eur'])}). Simple base payback is {best['payback_years']:.2f} years. Stage commitments through evidence and service gates; the arithmetic does not prove demand or a causal hub effect.")
d.add_paragraph(f"Strongest alternative by base-case ranking: {secondnames}, {eur(second['base_annual_incremental_eur'])} annual increment, {eur(second['capex_eur'])} capex, {second['fte']} FTE, low {eur(second['low_annual_incremental_eur'])}, stress {eur(second['stress_annual_incremental_eur'])}. Change the decision if validated volumes or avoidable savings fail to clear low/stress hurdles, or quotes exceed the €450,000/seven-FTE envelope.")
d.add_heading('2025 diagnosis',1)
d.add_paragraph(f"Synthetic revision-resolved records show {totals['shipped_orders']:,} eligible 2025 shipments and {totals['shipped_units']:,} units. Gross sales {eur(totals['gross_sales_eur'])} less credits/refunds {eur(totals['refunds_eur'])} yields net sales {eur(totals['net_sales_eur'])}. Net COGS is {eur(totals['net_cogs_eur'])}, fulfillment {eur(totals['fulfillment_eur'])}, leaving contribution {eur(totals['contribution_eur'])} ({margin:.1%} of net sales). Booked revenue is shipment-based sales less credits. Cash differs with settlement timing and working capital; contribution additionally deducts product and fulfillment costs. Cash receipts are absent, so cash conversion is not measurable here." )
d.add_picture(str(O/'country_contribution.png'),width=Inches(6.8)); d.add_paragraph('Figure 1. Contribution by country from synthetic 2025 records.',style='Caption')
d.add_paragraph('Czechia and Spain lead the modeled pair result because the supplied per-unit savings, units and fixed costs combine favorably under policy arithmetic. The option file does not independently evidence avoidable costs or service improvement. Validate savings against shipment-lane invoices and a central-hub comparator.')
d.add_heading('Options and scenarios',1)
t=d.add_table(rows=1,cols=8);t.style='Light Shading Accent 1'
for i,v in enumerate(['Portfolio','Capex','FTE','Low/year','Base/year','High/year','Stress/year','Payback']):t.rows[0].cells[i].text=v
for a in alts[:8]:
 row=t.add_row().cells; vals=[' + '.join(a['countries']),eur(a['capex_eur']),str(a['fte']),eur(a['low_annual_incremental_eur']),eur(a['base_annual_incremental_eur']),eur(a['high_annual_incremental_eur']),eur(a['stress_annual_incremental_eur']),f"{a['payback_years']:.2f}y" if a['payback_years'] else 'n/a']
 for i,v in enumerate(vals):row[i].text=v
d.add_picture(str(O/'alternatives.png'),width=Inches(6.8));d.add_paragraph('Figure 2. Top feasible alternatives, ranked by base annual contribution. Feasibility: at most two hubs, ≤€450k capex and ≤7 FTE.',style='Caption')
d.add_paragraph('Low/base/high uplifts are 10/25/40%. Annual increment = baseline contribution × uplift + baseline units × (1 + uplift) × savings/unit − annual fixed cost. Stress uses 25% volume, a refund shock of 3% gross with no cost recovery, and 10% depreciation against net sales for PLN/CZK markets. Stress has no assigned likelihood. Capex is a year-zero outlay, excluded from annual contribution. Simple payback is capex divided by positive base increment, without discounting.')
d.add_heading('Market context',1)
d.add_paragraph(f"Archived World Bank population grew {popdelta['ESP']:.2f}% in Spain and {popdelta['CZE']:.2f}% in Czechia from 2022 to 2024, while Poland declined {abs(popdelta['POL']):.2f}%. In 2024 current-US-dollar GDP per capita ranged from ${gdps[gdplo]:,.0f} in {N[gdplo]} to ${gdps[gdphi]:,.0f} in {N[gdphi]}. These are broad scale/economic context, not replacement-assembly demand evidence; GDP per capita is neither PPP nor constant-price real income. Full years and missingness are preserved in workbook; historical values may have revisions.")
d.add_heading('90-day implementation, owners and gates',1)
for h,txt in [('Days 0–30 | validate baseline','CFO + Commercial Operations reconcile order, invoice/credit, lane-cost and return records; sample carrier invoices. Gate 1: ≥98% record/cost linkage, cutoff and FX reviewed, Finance signs baseline. Dependency: operational-system access.'),('Days 31–60 | prove location case','COO + Regional Service, with Finance, HR and Procurement: verify catchment, addressable units, avoidable costs, local labor/carrier/lease quotes; design a reversible 3PL or central-stock pilot. Gate 2: rerun low/stress positive and remain within capex/FTE.'),('Days 61–90 | stage, commit or stop','CEO/Board sponsor + CFO stage release after demand evidence, exit clauses, named service owner, SLA and inventory controls. Gate 3: approve pilot/fit-out only if downside economics and service plan pass; otherwise defer with a dated review.')]:d.add_heading(h,2);d.add_paragraph(txt)
d.add_paragraph('Weekly KPI plan: OTIF vs central baseline, median order-to-delivery hours, expedite/fulfillment EUR per order, return rate and restock recovery, fill rate, eligible units, contribution after recurring hub costs, capex committed/forecast, FTE staffed. Owners: Regional Service (service), Supply Chain (inventory/delivery), Commercial Ops (units), Finance (economics), HR (staffing). Risks: synthetic assumptions may not transfer, capex/fixed costs may inflate, local stock may become obsolete, refund credits may precede recovery, realized FX may diverge, and ramp may delay savings.')
d.add_heading('Method, source and limitations',1)
d.add_paragraph('Highest numeric order revision replaces the whole earlier row; exact repeats collapse. Include shipped, non-test orders with 2025 shipment date, including free shipments. Resolve return revisions, include received through 2026-01-31 inclusive, and attach only to eligible order IDs. Unlinked returns are quarantined. Gross and summed refund use the original sale-month ECB arithmetic mean in local units per EUR (EUR=1); per-order components round half-up to cents. Latest effective unit cost applies; only restocked units recover COGS. Empty country-months are zeros, and margin is null for zero net sales.')
d.add_paragraph(f"Quality: {q['raw_order_rows']:,} raw order rows, {q['exact_duplicate_order_rows']} exact duplicate rows, {q['distinct_order_ids_after_revisions']:,} IDs after revision resolution, {q['eligible_shipped_2025_orders']:,} eligible orders; {q['raw_return_rows']} return rows, {q['attached_return_ids']} attached return IDs and {q['quarantined_or_unlinked_return_ids']} quarantined/unlinked. All {q['monthly_rows']} country-month records reconcile to country totals. Detailed anomaly counts and handling are in metrics.json and workbook.")
d.add_paragraph('Client orders, returns, costs and hub choices are entirely synthetic. Public evidence is a frozen source-room capture of official ECB historical rates and official World Bank API responses. WB archive lastupdated 2026-07-13 and captured 2026-09-27; historical revisions may be included. ECB reference rates are not realized transaction FX. No live account, interviews, geocoded demand, local quotes or causal savings study was accessed. Missing values are not imputed. Scenario model is simple and undiscounted; excludes ramp, tax, working capital, salvage and complete cash flows. Evidence URLs, retrieval times, hashes, units and labels are in evidence/source-register.csv; raw sources are under evidence/raw/.')
d.save(O/'board_report.docx')

# PDF executive report.
ss=getSampleStyleSheet();ss.add(ParagraphStyle(name='T',parent=ss['Title'],fontSize=24,textColor=colors.HexColor('#123843')));ss.add(ParagraphStyle(name='H',parent=ss['Heading1'],textColor=colors.HexColor('#167d86')));ss.add(ParagraphStyle(name='S',parent=ss['BodyText'],fontSize=8,leading=10))
story=[Paragraph('European service-hub expansion',ss['T']),Paragraph('Meridian Parts | Board decision paper | 27 September 2026',ss['Normal']),Spacer(1,12),Paragraph('Recommendation',ss['H']),Paragraph(f"Advance {names} as a gated case: {eur(rec['capex_eur'])} capex, {rec['fte']} FTE, {eur(best['base_annual_incremental_eur'])}/year base increment, {eur(best['low_annual_incremental_eur'])} low, {eur(best['stress_annual_incremental_eur'])} stress, {best['payback_years']:.2f}-year simple payback. The strongest alternative is {secondnames} ({eur(second['base_annual_incremental_eur'])}/year base). Validate before irreversible commitment.",ss['BodyText']),Paragraph('2025 synthetic operating baseline',ss['H']),]
table=[['Orders','Units','Gross','Refunds','Net sales','Net COGS','Fulfillment','Contribution','Margin'],[f"{totals['shipped_orders']:,}",f"{totals['shipped_units']:,}",eur(totals['gross_sales_eur']),eur(totals['refunds_eur']),eur(totals['net_sales_eur']),eur(totals['net_cogs_eur']),eur(totals['fulfillment_eur']),eur(totals['contribution_eur']),f'{margin:.1%}']]
story += [Table(table,repeatRows=1,style=TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#123843')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTSIZE',(0,0),(-1,-1),7),('GRID',(0,0),(-1,-1),.3,colors.grey)])),Paragraph('Booked revenue is shipments less credits; cash timing is absent. Contribution also deducts net COGS and fulfillment.',ss['S']),Image(str(O/'country_contribution.png'),width=6.5*inch,height=3.25*inch),Paragraph('Portfolio economics',ss['H'])]
table=[['Portfolio','Capex','FTE','Low','Base','High','Stress','Payback']]
for a in alts[:8]:table.append(['+'.join(a['countries']),eur(a['capex_eur']),str(a['fte']),eur(a['low_annual_incremental_eur']),eur(a['base_annual_incremental_eur']),eur(a['high_annual_incremental_eur']),eur(a['stress_annual_incremental_eur']),f"{a['payback_years']:.2f}y" if a['payback_years'] else 'n/a'])
story += [Table(table,repeatRows=1,style=TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#123843')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTSIZE',(0,0),(-1,-1),7),('GRID',(0,0),(-1,-1),.3,colors.grey)])),PageBreak(),Paragraph('90-day implementation and gates',ss['H']),Paragraph('<b>Days 0–30 | CFO + Commercial Operations:</b> join orders, credits, carrier lanes, cost and returns; review invoice samples. Gate 1: ≥98% record and cost coverage, FX and cutoff reviewed, Finance signs baseline. Dependency: operational-system access.',ss['BodyText']),Spacer(1,5),Paragraph('<b>Days 31–60 | COO + Regional Service:</b> validate catchment, addressable units, avoidable lane savings and delivery baseline; obtain lease, labor, carrier and fit-out quotes; design reversible pilot. Gate 2: economics remain positive in low volume and joint stress, within €450k and seven FTE.',ss['BodyText']),Spacer(1,5),Paragraph('<b>Days 61–90 | CEO/Board sponsor + CFO:</b> stage release after named owner, SLA, inventory controls and signed costs. Gate 3: approve pilot/fit-out only if evidence passes; otherwise defer with dated review.',ss['BodyText']),Spacer(1,5),Paragraph(f"<b>Market context:</b> World Bank population changed Spain {popdelta['ESP']:+.2f}%, Czechia {popdelta['CZE']:+.2f}%, Poland {popdelta['POL']:+.2f}% from 2022–24. 2024 GDP/capita was ${gdps[gdphi]:,.0f} in {N[gdphi]} and ${gdps[gdplo]:,.0f} in {N[gdplo]} (current US$); context only, not demand proof.",ss['BodyText']),Spacer(1,5),Paragraph('<b>Weekly KPI:</b> OTIF vs baseline, delivery hours, expedite EUR/order, return rate/restock recovery, fill rate, eligible units, contribution after recurring hub cost, capex forecast and FTE. Owners: Service, Supply Chain, Commercial Ops, Finance and HR. Risks include synthetic assumption transferability, quote inflation, stock obsolescence, delayed recovery, FX and ramp.',ss['BodyText']),PageBreak(),Paragraph('Evidence, accounting and limitations',ss['H']),Paragraph(f"Resolve highest revisions, include shipped non-test 2025 orders including free shipments, attach returns only through 2026-01-31 and quarantine unlinked IDs. Sale month ECB mean is local units per EUR; per-order components half-up to cents. Restocked units recover cost. Quality: {q['raw_order_rows']} order rows, {q['exact_duplicate_order_rows']} duplicate rows, {q['eligible_shipped_2025_orders']} eligible; {q['attached_return_ids']} return IDs attached, {q['quarantined_or_unlinked_return_ids']} quarantined. All 72 month-country rows reconcile. Client data/options are synthetic. Frozen official-source data: ECB and World Bank; WB lastupdated 2026-07-13, captured 2026-09-27. Missing values not imputed. Scenarios are assumption-driven, non-causal and undiscounted. No interviews or live account access. See source-register.csv and evidence/raw for source trail.",ss['BodyText'])]
SimpleDocTemplate(str(O/'board_report.pdf'),pagesize=letter,leftMargin=.48*inch,rightMargin=.48*inch,topMargin=.45*inch,bottomMargin=.45*inch).build(story)

# PPTX board deck.
prs=Presentation();prs.slide_width=PI(13.333);prs.slide_height=PI(7.5)
def slide(title,lines=None,img=None):
 s=prs.slides.add_slide(prs.slide_layouts[6]);s.background.fill.solid();s.background.fill.fore_color.rgb=RGBColor(248,250,249)
 band=s.shapes.add_shape(1,0,0,prs.slide_width,PI(.13));band.fill.solid();band.fill.fore_color.rgb=RGBColor(22,125,134);band.line.fill.background()
 tb=s.shapes.add_textbox(PI(.6),PI(.35),PI(12),PI(.25));p=tb.text_frame.paragraphs[0];p.text='MERIDIAN PARTS | BOARD DECISION';p.font.size=PP(10);p.font.bold=True;p.font.color.rgb=RGBColor(22,125,134)
 tb=s.shapes.add_textbox(PI(.6),PI(.75),PI(12),PI(.6));p=tb.text_frame.paragraphs[0];p.text=title;p.font.size=PP(27);p.font.bold=True;p.font.color.rgb=RGBColor(18,56,67)
 if img:s.shapes.add_picture(str(img),PI(.85),PI(1.55),width=PI(11.65))
 if lines:
  tb=s.shapes.add_textbox(PI(.8),PI(1.65),PI(11.8),PI(5.5));tf=tb.text_frame;tf.word_wrap=True
  for i,line in enumerate(lines):
   p=tf.paragraphs[0] if i==0 else tf.add_paragraph();p.text=line;p.font.size=PP(19 if i==0 else 16);p.font.color.rgb=RGBColor(44,62,66);p.space_after=PP(15)
slide('Advance a gated investment case',[f"Leading pair: {names} | base {eur(best['base_annual_incremental_eur'])}/year",f"Low {eur(best['low_annual_incremental_eur'])} | stress {eur(best['stress_annual_incremental_eur'])}",f"{eur(rec['capex_eur'])} capex | {rec['fte']} FTE | {best['payback_years']:.2f}-year payback","Stage commitment behind 90-day evidence and operating gates."])
slide('Contribution is not cash',[f"{totals['shipped_orders']:,} eligible orders | {totals['shipped_units']:,} units",f"Gross {eur(totals['gross_sales_eur'])} − refunds {eur(totals['refunds_eur'])} = net sales {eur(totals['net_sales_eur'])}",f"Less net COGS {eur(totals['net_cogs_eur'])} + fulfillment {eur(totals['fulfillment_eur'])} = contribution {eur(totals['contribution_eur'])}",f"Margin {margin:.1%}; cash settlement and working capital are absent."])
slide('Country contribution',img=O/'country_contribution.png');slide('Feasible portfolio economics',img=O/'alternatives.png')
slide('90-day gates and weekly scorecard',["0–30 days | CFO + Commercial Ops: ≥98% order/cost/return linkage; signed baseline.","31–60 days | COO + Service: validate catchment, avoidable cost and low/stress economics.","61–90 days | CEO/Board + CFO: staged commit after quote, SLA, owner and inventory sign-off.","Weekly: OTIF, delivery hours, expedite cost, return recovery, fill rate, units, contribution, capex, FTE."])
slide('Evidence limits',["Synthetic client inputs; no live account access or interviews.",f"WB 2022–24 population: Spain +{popdelta['ESP']:.2f}%, Czechia +{popdelta['CZE']:.2f}%, Poland {popdelta['POL']:.2f}%.",f"2024 GDP/capita current US$: {N[gdphi]} ${gdps[gdphi]:,.0f}; {N[gdplo]} ${gdps[gdplo]:,.0f}; context, not demand.","Frozen official ECB/WB archives; scenario math non-causal and undiscounted."])
prs.save(O/'board_deck.pptx')

# PDF version of the board slides, same narrative.
slides=[('Advance a gated investment case',[f"Leading pair: {names} | {eur(best['base_annual_incremental_eur'])}/year base",f"Low {eur(best['low_annual_incremental_eur'])} | stress {eur(best['stress_annual_incremental_eur'])}",f"{eur(rec['capex_eur'])} capex | {rec['fte']} FTE | {best['payback_years']:.2f}-year payback","Stage after 90-day validation"]),('Contribution is not cash',[f"{totals['shipped_orders']:,} orders | {totals['shipped_units']:,} units",f"Gross {eur(totals['gross_sales_eur'])} less refunds {eur(totals['refunds_eur'])} = net {eur(totals['net_sales_eur'])}",f"Net contribution {eur(totals['contribution_eur'])} | margin {margin:.1%}","Cash settlement data absent"]),('Country contribution',O/'country_contribution.png'),('Portfolio economics',O/'alternatives.png'),('90-day gates',["0–30: reconcile baseline ≥98% linkage.","31–60: validate savings and low/stress case.","61–90: board stage commit after service and cost sign-off.","Weekly: service, returns, units, contribution, capex, FTE."]),('Evidence limits',["Synthetic client data; no interviews/live account.",f"WB 2022–24 population: Spain +{popdelta['ESP']:.2f}%, Czechia +{popdelta['CZE']:.2f}%, Poland {popdelta['POL']:.2f}%.",f"2024 GDP/capita US$: {N[gdphi]} ${gdps[gdphi]:,.0f}; {N[gdplo]} ${gdps[gdplo]:,.0f}; not demand evidence.","Frozen official ECB/WB archives; scenarios non-causal and undiscounted."])]
pdf=[]
for title,content in slides:
 pdf += [Paragraph(title,ss['T']),Spacer(1,15)]
 if isinstance(content,Path):pdf.append(Image(str(content),width=10.2*inch,height=5*inch))
 else:
  for line in content:pdf += [Paragraph('• '+line,ss['Heading2']),Spacer(1,14)]
 pdf.append(PageBreak())
SimpleDocTemplate(str(O/'board_deck.pdf'),pagesize=landscape(letter),leftMargin=.6*inch,rightMargin=.6*inch,topMargin=.55*inch,bottomMargin=.55*inch).build(pdf)
print('Wrote report and presentation deliverables.')
